// 表示領域の不足と、隠れた要素を誤って拾うテストを区別するための追加確認。
import fs from 'node:fs';
import {chromium} from 'playwright-core';
const out='artifacts/responsive-reevaluation-20260913';
const b=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true});
let c,p;const result={};
async function start(w,h,lang){await c?.close();c=await b.newContext({viewport:{width:w,height:h},hasTouch:true,reducedMotion:'no-preference'});await c.route('https://**',r=>r.abort());await c.addInitScript(lang=>{if(location.protocol==='http:')localStorage.setItem('gaia:language:v1',lang);},lang);p=await c.newPage();p.setDefaultTimeout(15000);}
async function shot(id){await p.screenshot({path:`${out}/${id}.png`});}
async function map(){await p.goto('http://127.0.0.1:4492/#world-26');await p.locator('#gaia-boot').waitFor({state:'hidden'});await p.waitForTimeout(7000);}
const info=()=>{const root=document.querySelector('.japan-credits');return{root:{rect:root.getBoundingClientRect().toJSON(),scroll:root.scrollHeight,client:root.clientHeight,scrollTop:root.scrollTop},links:[...root.querySelectorAll('a')].filter(e=>e.checkVisibility({visibilityProperty:true})).map(e=>{const r=e.getBoundingClientRect();return{text:e.textContent,rect:r.toJSON(),hit:e.contains(document.elementFromPoint(r.x+r.width/2,r.y+r.height/2)),font:getComputedStyle(e).fontSize};})};};
try{
 await start(1024,768,'ja');await map();result.creditBefore=await p.evaluate(info);await shot('final-credit-ja-before');await p.locator('.japan-credits').hover();await p.mouse.wheel(0,500);await p.waitForTimeout(500);result.creditWheel=await p.evaluate(info);await shot('final-credit-ja-wheel');const links=p.locator('.japan-credits a:visible');await links.last().scrollIntoViewIfNeeded();await p.waitForTimeout(500);result.creditAutoScroll=await p.evaluate(info);await shot('final-credit-ja-auto-scroll');let native=true;try{await links.last().click({trial:true,timeout:1500});}catch{native=false;}result.creditNativeClickTrial=native;
 await start(320,568,'en');await map();await p.locator('[data-mobile-sheet="tools"]').click();await p.locator('.map-mobile-action-card').filter({hasText:'Statistical analysis'}).first().click();await p.waitForFunction(()=>globalThis.GaiaStatisticsLab?.getState().analysisReady);await p.waitForTimeout(700);await shot('final-analysis-small-en');
 result.graph=await p.locator('#gaia-statistics-visual').evaluate(e=>({rect:e.getBoundingClientRect().toJSON(),texts:[...e.querySelectorAll('svg text')].map(t=>({text:t.textContent,rect:t.getBoundingClientRect().toJSON()}))}));
 await start(844,390,'en');await p.goto('http://127.0.0.1:4492/#story');await p.locator('#gaia-boot').waitFor({state:'hidden'});await p.waitForFunction(()=>!!globalThis.GaiaNovel);await p.evaluate(()=>GaiaNovel.open(null,{autoStartFresh:true}));await p.waitForFunction(()=>document.querySelector('#novel-text')?.dataset.revealState==='complete',null,{timeout:40000});await p.locator('#novel-save-button').click();await p.waitForTimeout(700);await shot('final-save-landscape');
 result.save=await p.locator('#novel-save-slots').evaluate(e=>({rect:e.getBoundingClientRect().toJSON(),client:e.clientHeight,scroll:e.scrollHeight,first:e.firstElementChild.getBoundingClientRect().toJSON()}));await p.locator('#novel-save-slots').hover();await p.mouse.wheel(0,180);await p.waitForTimeout(500);await shot('final-save-landscape-scrolled');result.saveAfter=await p.locator('#novel-save-slots').evaluate(e=>({scrollTop:e.scrollTop,focused:document.activeElement.className}));
}catch(e){result.error=e.stack;}finally{fs.writeFileSync(`${out}/reading-final.json`,JSON.stringify(result,null,2));await b.close();}
